$result = [];
while ([$a, $b] = fgetcsv(STDIN, 1024, ',', '"', '')) {
    if (!isset($result[$a])) {
        $result[$a] = [$b];
    } else {
        $result[$a][] = $b;
    }
}
ksort($result);
foreach ($result as $i => $v) {
    sort($v);
    fputcsv(STDOUT, array_merge([$i], $v), ',', '"', '');
}
